// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMumbleEventHandler {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMumbleEventHandler = UniffiVTableCallbackInterfaceMumbleEventHandler(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceMumbleEventHandler.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface MumbleEventHandler: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceMumbleEventHandler.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface MumbleEventHandler: handle missing in uniffiClone")
            }
        },
        onConnectionStatusChanged: { (
            uniffiHandle: UInt64,
            status: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterCallbackInterfaceMumbleEventHandler.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onConnectionStatusChanged(
                     status: try FfiConverterTypeConnectionStatus_lift(status)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        onChannelsUpdated: { (
            uniffiHandle: UInt64,
            channels: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
